        // Day 3: Hit rate limiting not mentioned in test environment
        // Had to implement exponential backoff retry logic
        var result = retryWithBackoff(() -> 
            apiClient.charge(request, accessToken)
        );

        // Day 4: Finally working, but 2 days late
        // Lesson: Always read full API docs, not just examples
        // Lesson: Ask if anyone's integrated this vendor before
        return result;
    }
}

// What I did right: Told team lead on Day 2 morning that 
